using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace AboutMe.Editor
{
    public static class PartyControlTests
    {
        static readonly FieldInfo Cache=typeof(CampusGeometry).GetField("solids",BindingFlags.NonPublic|BindingFlags.Static);
        public static CampusSolid[] Flat=>PartyMachineryTests.Flat;
        static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        public static void Place(Match m,Player p,Vector3 pos)=>PartyMachineryTests.Place(m,p,pos);
        public static void Escape(Match m,string who,float seconds)
        {for(int i=0;i<Mathf.CeilToInt(seconds/.02f);i++){foreach(var p in m.Players.Values)m.Receive(p.profile.playerId,new Command{sequence=p.sequence+1,yaw=p.yaw,escapeHeld=p.profile.playerId==who});m.Tick(.02f);}}
        public static EffectState Deploy(Match m)
        {if(PartyMechanicRegistry.ForVisual(m.Item(m.Players["p0"].equipped).asset.visualId).id!="body-bank")return PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.25f,"p0",0,1);PartyFieldTests.Input(m,"p0","use_item",0,1);PartyFieldTests.Tick(m,.28f,"p0",0,1);return m.Effects.Last(x=>x.mechanicId=="body-bank");}
        public static EffectState Attached(Match m,string id)
        {var b=m.Players["p1"];Place(m,b,new Vector3(0,1,2.4f));var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.25f);Check(e.stage=="attached"&&e.targetId=="p1",id+" did not attach: "+e.stage+" at="+e.position+" player="+b.position);return e;}
        [MenuItem("About Me/Tests/Control and momentum authority")]
        public static void Run()
        {
            var old=Cache.GetValue(null);var failures=new List<string>();int passed=0;
            void Test(string name,Action run){Cache.SetValue(null,Flat);try{run();passed++;Debug.Log("PARTY_CONTROL_PASS "+name);}catch(Exception e){failures.Add(name+": "+e.Message);Debug.LogError("PARTY_CONTROL_FAIL "+name+": "+e);}}
            try
            {
                Test("ten control definitions bind ten unique actual models",()=>{var all=PartyMechanicRegistry.All.Where(x=>x.family=="control").ToArray();Check(all.Length==10&&all.Select(x=>x.id).Distinct().Count()==10&&all.Select(x=>x.visualId).Distinct().Count()==10,"registry incomplete");foreach(var d in all)Check(Resources.Load<GameObject>("PersonaProps/"+d.visualId)!=null,"missing prefab "+d.visualId);});
                Test("lasso permits both inputs and held Q really breaks it",()=>{using(var m=PartyFieldTests.Make("lasso-loop")){var b=m.Players["p1"];Place(m,b,new Vector3(0,1,3));var e=PartyFieldTests.Deploy(m);float a=m.Players["p0"].position.z,oldB=b.position.z;PartyFieldTests.Tick(m,.25f,"p1",1,0);Check(m.Effects.Contains(e)&&b.position.x>.8f&&m.Players["p0"].position.z>a&&b.stability==100,"lasso locked input/damaged/no reciprocal pull");Check(m.View("p1").players.First(x=>x.id=="p1").sticky,"Q affordance missing");Escape(m,"p1",.72f);Check(!m.Effects.Contains(e)&&m.Remaining("p1")==4,"held Q failed or cost life");}});
                Test("lasso rejects invisible target and detaches around wall",()=>{using(var m=PartyFieldTests.Make("lasso-loop")){Place(m,m.Players["p1"],new Vector3(0,1,3));var e=PartyFieldTests.Deploy(m);Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(0,1,1.4f),size=new Vector3(5,2,.2f)}}).ToArray());PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e),"lasso crossed wall");var n=PartyFieldTests.Make("lasso-loop");Place(n,n.Players["p1"],new Vector3(0,1,3));PartyFieldTests.Input(n,"p0","use_item");PartyFieldTests.Tick(n,.4f);Check(!n.Effects.Any(e2=>e2.mechanicId=="lasso-loop")&&n.View("p0").players.First().mechanicCooldown<1,"invisible target spent cooldown");n.Dispose();}});
                Test("net bounds movement but permits jump and full escape",()=>{using(var m=PartyFieldTests.Make("break-net")){var e=Attached(m,"net");var b=m.Players["p1"];var start=b.position;PartyFieldTests.Tick(m,.5f,"p1",1,0);Check(b.position.x>start.x+.4f&&Vector2.Distance(new Vector2(b.position.x,b.position.z),new Vector2(e.position.x,e.position.z))<=1.12f,"net locked or escaped boundary");PartyFieldTests.Input(m,"p1","jump");PartyFieldTests.Tick(m,.08f);Check(b.airborne,"net blocked jump");Escape(m,"p1",.72f);Check(!m.Effects.Contains(e),"net held Q failed");}});
                Test("net can be dismantled without consuming source",()=>{using(var m=PartyFieldTests.Make("break-net")){var e=Attached(m,"net");e.health=1;Place(m,m.Players["p2"],e.position+Vector3.back*1.5f);var source=m.Item(m.Players["p2"].equipped);source.asset.templateId="Melee";PartyFieldTests.Input(m,"p2","use_item");PartyFieldTests.Tick(m,.4f);Check(!m.Effects.Contains(e)&&m.Remaining("p0")==4,"net did not dismantle / consumed life");}});
                Test("bubble rises bounded height allows drift and Q frees",()=>{using(var m=PartyFieldTests.Make("bubble-lift")){var e=Attached(m,"bubble");var b=m.Players["p1"];float y=b.motorHeight;PartyFieldTests.Tick(m,.35f,"p1",1,0);Check(b.position.x>1&&b.motorHeight>y+.2f&&b.motorHeight<=e.height+.72f&&b.stability==100,"bubble height/drift/damage");Escape(m,"p1",.72f);Check(!m.Effects.Contains(e),"bubble Q failed");}});
                Test("bubble breaks when target attacks or gets grabbed",()=>{foreach(bool attack in new[]{true,false})using(var m=PartyFieldTests.Make("bubble-lift")){var e=Attached(m,"bubble");if(attack){m.Item(m.Players["p1"].equipped).asset.templateId="Melee";PartyFieldTests.Input(m,"p1","use_item");PartyFieldTests.Tick(m,.35f);}else{Place(m,m.Players["p2"],m.Players["p1"].position+Vector3.back*.9f);m.Players["p2"].grabbing="p1";m.Players["p2"].grabKind="body";m.Players["p2"].grabStartedAt=m.Time;PartyFieldTests.Tick(m,.02f);}Check(!m.Effects.Contains(e),"bubble survived attack/grab="+attack);}});
                Test("U cage has physical walls and open front no enclosed victim",()=>{using(var m=PartyFieldTests.Make("gapped-cage")){var e=PartyFieldTests.Deploy(m);Check(Match.MachineShapes(e).Count()==3,"U cage geometry");var b=m.Players["p1"];Place(m,b,e.position+Vector3.up*.85f);var from=b.position;Check(m.MoveOnMachines(from,from+Vector3.right*1.3f)==from,"side wall not solid");Check(m.MoveOnMachines(from,from+Vector3.forward*1.5f)!=from,"front gap blocked");PartyFieldTests.Tick(m,.6f,"p1",0,1);Check(b.position.z>e.position.z+2&&b.stability==100,"could not walk out");var blocked=PartyFieldTests.Make("gapped-cage");Place(blocked,blocked.Players["p1"],new Vector3(0,1,3.7f));PartyFieldTests.Input(blocked,"p0","use_item");PartyFieldTests.Tick(blocked,.4f);Check(blocked.Effects.Count==0,"cage placed over victim");blocked.Dispose();}});
                Test("water jet pushes with recoil no damage and ground owner unchanged",()=>{using(var m=PartyFieldTests.Make("water-jet")){var b=m.Players["p1"];Place(m,b,new Vector3(0,1,2.6f));var life=PartyFieldTests.Ground(m,new Vector3(.2f,.35f,3));float z=life.position.z;var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.3f);Check(b.position.z>2.7f&&life.position.z>z+.1f&&m.Players["p0"].position.z<-.05f&&b.stability==100&&life.ownerId=="p2"&&life.state==ItemState.Ground,"jet/recoil/life wrong a="+m.Players["p0"].position+" b="+b.position+" life="+life.position+" start="+z);PartyFieldTests.Input(m,"p0","cancel");Check(!m.Effects.Contains(e),"jet Q failed");}});
                Test("wall blocks water and source drop ends channel",()=>{using(var m=PartyFieldTests.Make("water-jet")){Place(m,m.Players["p1"],new Vector3(0,1,3));Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(0,1,1.5f),size=new Vector3(4,2,.2f)}}).ToArray());var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.4f);Check(Mathf.Abs(m.Players["p1"].position.z-3)<.01f,"water crossed wall");m.Drop(m.Players["p0"],1);PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&m.Remaining("p0")==4,"unequipped jet persisted/life count");}});
                Test("team sling requires second person's E and stops on Q",()=>{using(var m=PartyFieldTests.Make("team-sling")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];Place(m,b,e.position+Vector3.up*.85f);PartyFieldTests.Tick(m,.5f);Check(!b.airborne&&e.stage=="ready","auto forced launch");PartyFieldTests.Input(m,"p1","interact");Check(e.stage=="launch_warning","no consent warning");PartyFieldTests.Input(m,"p1","cancel");PartyFieldTests.Tick(m,.5f);Check(e.stage=="ready"&&!b.airborne,"Q did not cancel consent");PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Tick(m,.5f);Check(b.airborne&&b.motorHeight>1.15f&&m.CombatEvents.Count(x=>x.kind=="party_team_launch")==1,"consented launch missing");}});
                Test("ground E and operator movement counter team sling",()=>{using(var m=PartyFieldTests.Make("team-sling")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];Place(m,b,e.position+Vector3.up*.85f);var life=PartyFieldTests.Ground(m,e.position+Vector3.up*.2f);PartyFieldTests.Input(m,"p1","interact");Check(life.state==ItemState.Carried&&e.stage=="ready","sling stole ground E");m.Interrupt(b);life.position=new Vector3(20,.35f,20);PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Tick(m,.3f,"p0",1,0);Check(e.stage=="ready"&&!b.airborne,"moving operator did not cancel");}});
                Test("body bank requires speed and reflects once from wall",()=>{using(var m=PartyFieldTests.Make("body-bank")){PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.35f);Check(!m.Effects.Any(x=>x.mechanicId=="body-bank"),"stationary free bounce");m.Players["p0"].nextAttack=0;PartyFieldTests.Tick(m,.4f,"p0",0,1);Place(m,m.Players["p0"],new Vector3(0,1,0));m.Players["p0"].velocity=Vector3.forward*5.5f;var e=Deploy(m);Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=m.Players["p0"].position+Vector3.forward*1.2f,size=new Vector3(5,2,.2f)}}).ToArray());PartyFieldTests.Tick(m,.8f);Check(m.CombatEvents.Count(x=>x.kind=="party_body_reflect")==1&&!m.Effects.Contains(e),"bounce missing/repeated");}});
                Test("rolling prop transfers limited momentum only to public objects",()=>{using(var m=PartyFieldTests.Make("momentum-pass")){var prop=new PublicProp{id="crate",visual="box",position=new Vector3(0,.6f,3)};m.Props.Add(prop);var life=PartyFieldTests.Ground(m,new Vector3(.9f,.35f,2));var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.3f);Check(prop.position.z>3.2f&&m.CombatEvents.Count(x=>x.kind=="party_momentum_transfer")==1&&e.velocity.magnitude<2&&life.ownerId=="p2"&&Mathf.Abs(life.position.z-2)<.01f,"momentum transfer duplicated/changed life");Check(m.CombatEvents.First(x=>x.kind=="party_momentum_transfer").impulse.magnitude<5.6f,"energy increased");}});
                Test("held public prop excluded and wall stops rolling ball",()=>{using(var m=PartyFieldTests.Make("momentum-pass")){m.Props.Add(new PublicProp{id="held",visual="box",holder="p1",position=new Vector3(0,.6f,3)});Cache.SetValue(null,Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(0,1,2),size=new Vector3(5,2,.2f)}}).ToArray());PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.5f);Check(!m.CombatEvents.Any(x=>x.kind=="party_momentum_transfer"),"transfer through wall or into held box");}});
                Test("skate preserves inertia turns slowly and Q brakes",()=>{using(var m=PartyFieldTests.Make("skate-arc")){var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.25f,"p0",1,0);var a=m.Players["p0"];Check(a.position.z>.3f&&e.velocity.z>e.velocity.x&&e.velocity.x>0,"arc did instant turn");float z=a.position.z;PartyFieldTests.Tick(m,.15f);Check(a.position.z>z+.1f,"no input killed inertia");PartyFieldTests.Input(m,"p0","cancel");z=a.position.z;PartyFieldTests.Tick(m,.1f);Check(!m.Effects.Contains(e)&&Mathf.Abs(a.position.z-z)<.05f,"Q did not brake");}});
                Test("skate collision stops and prevents simultaneous eating",()=>{using(var m=PartyFieldTests.Make("skate-arc")){var life=PartyFieldTests.Ground(m,new Vector3(.2f,.35f,0));Place(m,m.Players["p1"],new Vector3(0,1,2));var e=PartyFieldTests.Deploy(m);PartyFieldTests.Input(m,"p0","interact");Check(life.state==ItemState.Ground,"ate while skating");PartyFieldTests.Tick(m,.6f,"p0",0,1);Check(!m.Effects.Contains(e)&&m.Players["p1"].stability==100,"collision did not stop or damaged life");}});
                Test("anchor swing follows circular tangent and moving anchor breaks",()=>{using(var m=PartyFieldTests.Make("anchor-swing")){m.Props.Add(new PublicProp{id="anchor",visual="box",position=new Vector3(0,.6f,3)});var e=PartyFieldTests.Deploy(m);float radius=e.radius;PartyFieldTests.Tick(m,.4f,"p0",1,0);var a=m.Players["p0"];Check(a.position.x>.35f&&Mathf.Abs(Vector2.Distance(new Vector2(a.position.x,a.position.z),new Vector2(0,3))-radius)<.12f,"swing pulled straight instead of orbit");m.Props[0].holder="p1";m.Players["p1"].publicProp="anchor";PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e),"grabbed anchor did not break");}});
                Test("Q releases swing with tangent momentum but no extra life",()=>{using(var m=PartyFieldTests.Make("anchor-swing")){m.Props.Add(new PublicProp{id="anchor",visual="box",position=new Vector3(0,.6f,3)});var e=Deploy(m);PartyFieldTests.Tick(m,.4f,"p0",1,0);var a=m.Players["p0"];float x=a.position.x;PartyFieldTests.Input(m,"p0","cancel");PartyFieldTests.Tick(m,.08f);Check(!m.Effects.Contains(e)&&a.position.x>x+.05f&&m.Remaining("p0")==4,"Q killed tangent momentum or consumed life");}});
                Test("control effect cap and source disconnect clean self only",()=>{using(var m=PartyFieldTests.Make("water-jet")){var e=Deploy(m);m.Disconnect("p0");Check(!m.Effects.Contains(e)&&m.Remaining("p0")==4,"disconnect left channel/lost life");}using(var m=PartyFieldTests.Make("gapped-cage")){for(int i=0;i<8;i++)m.Effects.Add(new EffectState{id="old"+i,kind="PartyMechanic",owner="p1",sourceInstance=m.Players["p1"].equipped,mechanicId="spring-pad",stage="deployed",position=new Vector3(-20,.15f,i),deadline=m.Time+6});PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.4f);Check(m.Effects.Count==8&&m.View("p0").players.First(x=>x.id=="p0").mechanicCooldown<1,"ninth cage bypassed budget or spent cooldown");}});
                Test("source consume finish disconnect cleanup and original life conservation",()=>{foreach(var d in PartyMechanicRegistry.All.Where(x=>x.family=="control")){using(var m=PartyFieldTests.Make(d.id)){if(d.id=="lasso-loop")Place(m,m.Players["p1"],new Vector3(0,1,3));if(d.id=="anchor-swing")m.Props.Add(new PublicProp{id="anchor",visual="box",position=new Vector3(0,.6f,3)});if(d.id=="body-bank")m.Players["p0"].velocity=Vector3.forward*3;var e=Deploy(m);m.Item(e.sourceInstance).state=ItemState.Consumed;PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&m.Remaining("p0")==3&&m.Remaining("p1")==4,"consume leaks or modifies target "+d.id);m.Finish("timeout");Check(!m.Effects.Any(x=>x.kind=="PartyMechanic"),"finish leak "+d.id);}}});
            }
            finally{Cache.SetValue(null,old);}if(failures.Count>0)throw new Exception(string.Join("\n",failures));Debug.Log("PARTY_CONTROL_PASSED "+passed+" authority scenarios / ten control-momentum decisions");
        }
    }
}
